import { test } from "node:test";
import assert from "node:assert/strict";
import {
  emitDomainModel,
  emitDomain,
  emitDomainBindings,
  deriveDomain,
  sourcesFromManifest,
  registryFromManifest,
  sqliteAffinityToTs,
  interfaceName,
  type SourceSchema,
  type TableMeta,
  type DomainTypeRegistry,
} from "./domain.ts";
import type { ToolkitManifest } from "./migrations.ts";

// Goldens captured verbatim from the console's `emitDomainModel` (server domain_types.ts) via
// Deno — this IS the per-emitter drift gate (ADR 0053): the toolkit must be byte-identical.
const GOLDENS: Record<string, string> = JSON.parse("{\n  \"empty\": \"// AUTO-GENERATED by nanobpmn from the datasource schema (ADR 0029 §4.1).\\n// Do not edit — regenerated from the live tables. Erased at `deno compile`.\\n// eslint-disable\\n\\nexport interface DomainTables {}\\n\",\n  \"tablesOnly\": \"// AUTO-GENERATED by nanobpmn from the datasource schema (ADR 0029 §4.1).\\n// Do not edit — regenerated from the live tables. Erased at `deno compile`.\\n// eslint-disable\\n\\nexport interface Customers {\\n  /** INTEGER (primary key) */\\n  id: number;\\n  /** TEXT */\\n  email: string;\\n  /** TEXT */\\n  tier: string | null;\\n}\\n\\nexport interface OrderItems {\\n  /** INTEGER (primary key) */\\n  id: number;\\n  /** INTEGER */\\n  qty: number;\\n  /** REAL */\\n  \\\"unit price\\\": number | null;\\n}\\n\\n/** Every table keyed by its wire name — index it for a row type. */\\nexport interface DomainTables {\\n  \\\"customers\\\": Customers;\\n  \\\"order_items\\\": OrderItems;\\n}\\n\",\n  \"typesOnly\": \"// AUTO-GENERATED by nanobpmn from the datasource schema (ADR 0029 §4.1).\\n// Do not edit — regenerated from the live tables. Erased at `deno compile`.\\n// eslint-disable\\n\\nexport interface DomainTables {}\\n\\n/** Declared (transient) domain types from the manifest `types` registry (ADR 0029 §4.2), keyed by id. */\\nexport interface DomainTypes {\\n  \\\"taxReturn\\\": {\\n    year: number;\\n    notes?: string;\\n    lines: DomainTypes[\\\"lineItem\\\"][];\\n  };\\n  \\\"lineItem\\\": {\\n    \\\"line no\\\": number;\\n    amount: number;\\n  };\\n}\\n\",\n  \"both\": \"// AUTO-GENERATED by nanobpmn from the datasource schema (ADR 0029 §4.1).\\n// Do not edit — regenerated from the live tables. Erased at `deno compile`.\\n// eslint-disable\\n\\nexport interface Greetings {\\n  /** INTEGER (primary key) */\\n  id: number;\\n  /** TEXT */\\n  who: string;\\n  /** TEXT */\\n  message: string;\\n  /** TEXT */\\n  createdAt: string | null;\\n}\\n\\n/** Every table keyed by its wire name — index it for a row type. */\\nexport interface DomainTables {\\n  \\\"greetings\\\": Greetings;\\n}\\n\\n/** Declared (transient) domain types from the manifest `types` registry (ADR 0029 §4.2), keyed by id. */\\nexport interface DomainTypes {\\n  \\\"greeting\\\": {\\n    who: string;\\n    message: string;\\n    createdAt?: string;\\n  };\\n}\\n\",\n  \"multi\": \"// AUTO-GENERATED by nanobpmn from the datasource schemas (ADR 0029 §4.1/§6).\\n// Do not edit — regenerated from the live tables. Erased at `deno compile`.\\n// eslint-disable\\n\\nexport interface AppCustomers {\\n  /** INTEGER (primary key) */\\n  id: number;\\n  /** TEXT */\\n  email: string;\\n}\\n\\nexport interface AnalyticsEvents {\\n  /** INTEGER (primary key) */\\n  id: number;\\n  /** TEXT */\\n  kind: string;\\n}\\n\\n/** Every datasource keyed by alias, then table by wire name. */\\nexport interface DomainSources {\\n  \\\"app\\\": {\\n    \\\"customers\\\": AppCustomers;\\n  };\\n  \\\"analytics\\\": {\\n    \\\"events\\\": AnalyticsEvents;\\n  };\\n}\\n\\n/** The default datasource's tables — index by wire name. */\\nexport type DomainTables = DomainSources[\\\"analytics\\\"];\\n\"\n}");

const col = (name: string, type: string, notNull: boolean, primaryKey: boolean) =>
  ({ name, type, notNull, primaryKey });
const table = (name: string, cols: TableMeta["columns"], kind: TableMeta["kind"] = "table"): TableMeta => ({ name, kind, columns: cols, indexes: [], foreignKeys: [] });

test("emitDomainModel: empty app → bare DomainTables (byte-parity)", () => {
  assert.equal(emitDomainModel([], undefined, {}), GOLDENS.empty);
});

test("emitDomainModel: table spine only (byte-parity)", () => {
  const sources: SourceSchema[] = [{ source: "app", tables: [
    table("customers", [col("id","INTEGER",false,true), col("email","TEXT",true,false), col("tier","TEXT",false,false)]),
    table("order_items", [col("id","INTEGER",false,true), col("qty","INTEGER",true,false), col("unit price","REAL",false,false)]),
  ]}];
  assert.equal(emitDomainModel(sources, "app", {}), GOLDENS.tablesOnly);
});

test("emitDomainModel: registry only — nominal ref, list, optional, non-ident key (byte-parity)", () => {
  const types: DomainTypeRegistry = {
    taxReturn: { fields: { year: { type: "integer" }, notes: { type: "string", optional: true }, lines: { type: "lineItem", list: true } } },
    lineItem: { fields: { "line no": { type: "integer" }, amount: { type: "number" } } },
  };
  assert.equal(emitDomainModel([], undefined, types), GOLDENS.typesOnly);
});

test("emitDomainModel: table + registry coexist for same type (byte-parity)", () => {
  const sources: SourceSchema[] = [{ source: "app", tables: [
    table("greetings", [col("id","INTEGER",false,true), col("who","TEXT",true,false), col("message","TEXT",true,false), col("createdAt","TEXT",false,false)]),
  ]}];
  const types: DomainTypeRegistry = { greeting: { table: "greetings", fields: { who: { type: "string" }, message: { type: "string" }, createdAt: { type: "datetime", optional: true } } } };
  assert.equal(emitDomainModel(sources, "app", types), GOLDENS.both);
});

test("emitDomainModel: multi-source → DomainSources + DomainTables alias to default (byte-parity)", () => {
  const sources: SourceSchema[] = [
    { source: "app", tables: [ table("customers", [col("id","INTEGER",false,true), col("email","TEXT",true,false)]) ] },
    { source: "analytics", tables: [ table("events", [col("id","INTEGER",false,true), col("kind","TEXT",true,false)]) ] },
  ];
  assert.equal(emitDomainModel(sources, "analytics", {}), GOLDENS.multi);
});

test("emitDomainModel: a VIEW yields a read-only row interface (readonly fields)", () => {
  // The datasource read path works verbatim on a view, so consumers still get a typed row —
  // but a view is read-only in SQLite, so its fields are emitted `readonly`.
  const sources: SourceSchema[] = [{ source: "app", tables: [
    table("orders", [col("id","INTEGER",false,true), col("total","INTEGER",true,false)]),
    table("paid_orders", [col("id","INTEGER",false,false), col("total","INTEGER",false,false)], "view"),
  ]}];
  const out = emitDomainModel(sources, "app", {});
  // A base table stays writable (non-readonly fields).
  assert.match(out, /export interface Orders \{\n {2}\/\*\* INTEGER \(primary key\) \*\/\n {2}id: number;/);
  // The view's row interface is entirely read-only.
  assert.match(out, /export interface PaidOrders \{\n {2}\/\*\* INTEGER \*\/\n {2}readonly id: number \| null;\n {2}\/\*\* INTEGER \*\/\n {2}readonly total: number \| null;\n\}/);
  // Both appear in the DomainTables lookup — a view is a readable object.
  assert.match(out, /"paid_orders": PaidOrders;/);
});

test("emitDomainBindings: a VIEW gets NO Table<T> writer binding; base tables do", () => {
  const sources: SourceSchema[] = [{ source: "app", tables: [
    table("orders", [col("id","INTEGER",false,true), col("total","INTEGER",true,false)]),
    table("paid_orders", [col("id","INTEGER",false,false), col("total","INTEGER",false,false)], "view"),
  ]}];
  const bindings = emitDomainBindings(sources, "app");
  // The base table gets a typed Table<T> gateway (insert/update/delete available).
  assert.match(bindings, /readonly orders: Table<Orders>;/);
  assert.match(bindings, /orders: raw\.table<Orders>\("orders", "id"\),/);
  // The view is NOT offered a writer binding — it never appears as a Table<T> field or bind.
  assert.equal(bindings.includes("paid_orders"), false);
  assert.equal(bindings.includes("PaidOrders"), false);
});

// --- manifest bridge: code-first derivation reproduces the console output --------------------

test("emitDomain: manifest types drive BOTH the table spine and the registry (byte-parity)", () => {
  const manifest: ToolkitManifest = {
    data: { default: "app" },
    types: { greeting: { table: "greetings", fields: {
      who: { type: "string" }, message: { type: "string" }, createdAt: { type: "datetime", optional: true },
    } } },
  };
  // The manifest 'greeting' type yields DomainTables["greetings"] (id + fields) and
  // DomainTypes["greeting"] (declared fields only) — identical to the console's `both` case.
  assert.equal(emitDomain(manifest), GOLDENS.both);
});

test("sourcesFromManifest: implicit id PK + field affinity + nullability", () => {
  const manifest: ToolkitManifest = { data: { default: "app" }, types: {
    greeting: { table: "greetings", fields: { who: { type: "string" }, createdAt: { type: "datetime", optional: true } } },
  } };
  const [src] = sourcesFromManifest(manifest);
  assert.equal(src.source, "app");
  assert.deepEqual(src.tables[0], table("greetings", [
    col("id", "INTEGER", false, true),
    col("who", "TEXT", true, false),
    col("createdAt", "TEXT", false, false),
  ]));
});

test("sourcesFromManifest: table name defaults to the type id; types group by source", () => {
  const manifest: ToolkitManifest = { data: { default: "app" }, types: {
    order: { fields: { total: { type: "number" } } },
    event: { source: "analytics", fields: { kind: { type: "string" } } },
  } };
  const sources = sourcesFromManifest(manifest);
  assert.deepEqual(sources.map((s) => s.source), ["app", "analytics"]);
  assert.equal(sources[0].tables[0].name, "order");
  assert.equal(sources[1].tables[0].name, "event");
});

test("registryFromManifest: declared fields only (no persisted id); type defaults to string", () => {
  const manifest: ToolkitManifest = { types: {
    greeting: { table: "greetings", fields: { who: {}, note: { type: "string", optional: true } } },
  } };
  assert.deepEqual(registryFromManifest(manifest), {
    greeting: { table: "greetings", fields: { who: { type: "string", optional: undefined, list: undefined }, note: { type: "string", optional: true, list: undefined } } },
  });
});

test("registryFromManifest + emitDomain: the `list` modifier is preserved as `T[]`", () => {
  const manifest: ToolkitManifest = { types: {
    order: { fields: { tags: { type: "string", list: true } } },
  } };
  // The bridge must forward `list` (not drop it) so the emitter can project the repeated field.
  assert.equal(registryFromManifest(manifest).order.fields.tags.list, true);
  assert.match(emitDomain(manifest), /tags: string\[\];/);
});

test("deriveDomain: emits domain-rows.d.ts only when the manifest declares types", () => {
  assert.deepEqual(deriveDomain({}), []);
  assert.deepEqual(deriveDomain({ types: {} }), []);
  const arts = deriveDomain({ data: { default: "app" }, types: { greeting: { table: "greetings", fields: { who: { type: "string" } } } } });
  assert.equal(arts.length, 1);
  assert.equal(arts[0].path, "nano-generated/domain-rows.d.ts");
});

test("sqliteAffinityToTs: SQLite affinity rules with boolean/datetime overrides", () => {
  assert.equal(sqliteAffinityToTs("INTEGER"), "number");
  assert.equal(sqliteAffinityToTs("TEXT"), "string");
  assert.equal(sqliteAffinityToTs("REAL"), "number");
  assert.equal(sqliteAffinityToTs("BLOB"), "Uint8Array");
  assert.equal(sqliteAffinityToTs("BOOLEAN"), "boolean");
  assert.equal(sqliteAffinityToTs("DATETIME"), "string");
  assert.equal(sqliteAffinityToTs("NUMERIC"), "number");
  assert.equal(sqliteAffinityToTs(""), "unknown");
});

test("interfaceName: PascalCases + sanitises table names to identifiers", () => {
  assert.equal(interfaceName("order_items"), "OrderItems");
  assert.equal(interfaceName("customers"), "Customers");
  assert.equal(interfaceName("2024_events"), "T_2024Events");
});
